import { spawnSync } from 'node:child_process';

import { EXECUTABLE_PATH } from '../constants.mjs';

export function runExecutable(argv) {
  const result = spawnSync(EXECUTABLE_PATH, argv, {
    encoding: 'utf8',
    maxBuffer: 10 * 1024 * 1024,
  });

  if (result.error) {
    throw result.error;
  }

  return {
    status: typeof result.status === 'number' ? result.status : 1,
    stdout: result.stdout ?? '',
    stderr: result.stderr ?? '',
  };
}

const LONG_HELP_TOKENS = new Set(['--h', '--he', '--hel', '--help']);

function isShortHelpCluster(token) {
  return token.length > 1 && token[0] === '-' && token[1] === 'h' && (token.length === 2 || token[2] !== '=');
}

export function isHelpInvocation(argv) {
  for (const token of argv) {
    if (typeof token !== 'string') {
      continue;
    }

    if (LONG_HELP_TOKENS.has(token)) {
      return true;
    }

    if (token[0] === '-' && token[1] !== '-' && isShortHelpCluster(token)) {
      return true;
    }
  }

  return false;
}

export function tryParseCliArgs(argv) {
  let a;
  let b;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '--a' || token === '--b') {
      const next = argv[index + 1];

      if (next === undefined || (next.length > 0 && next[0] === '-')) {
        return { kind: 'delegate' };
      }

      if (token === '--a') {
        a = next;
      } else {
        b = next;
      }

      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      a = token.slice(4);
      continue;
    }

    if (token.startsWith('--b=')) {
      b = token.slice(4);
      continue;
    }

    return { kind: 'delegate' };
  }

  if (a === undefined || b === undefined) {
    return { kind: 'delegate' };
  }

  return {
    kind: 'ok',
    a,
    b,
  };
}

